def ratio(key,label,value,variables):
 num,den=s.fraction(s.cancel(value));return f(key,label,[num,den],'ratio',variables)
def ip(F):
 first=-s.diff(F,x)/s.diff(F,y);second=-(s.diff(F,x,2)+2*s.diff(F,x,y)*first+s.diff(F,y,2)*first**2)/s.diff(F,y)
 return s.cancel(first),s.cancel(second)
